// Better Auth for CeFi: account number + 6-digit PIN (username plugin, the PIN
// is the "password") or passkey. No email: the user table's required email is
// a per-account .invalid placeholder (see account.ts).
//
// Built by a factory so tests can run it against an in-memory DB and storage.
// Tables are prefixed cefi_ in the shared SQLite DB (schema.ts, generated by
// the Better Auth CLI; see the README).

import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { APIError, createAuthMiddleware, isAPIError } from "better-auth/api";
import { username } from "better-auth/plugins";
import { passkey } from "@better-auth/passkey";
import type { BunSQLiteDatabase } from "drizzle-orm/bun-sqlite";
import { CEFI } from "../../config/cefi";
import {
  hashPin,
  isAccountNumber,
  isValidPin,
  normalizeAccountNumber,
  verifyPin,
} from "./account";
import { PinLockout } from "./lockout";
import * as schema from "./schema";
import type { CefiStorage } from "./storage";

export interface CefiAuthDeps {
  db: BunSQLiteDatabase<any>;
  storage: CefiStorage;
  secret: string; // BETTER_AUTH_SECRET: signs cookies and tokens
  pinPepper: string; // CEFI_PIN_PEPPER: see account.ts
  baseURL: string;
  rpID: string;
  origins: string[];
}

const PIN_ERROR = `PIN must be exactly ${CEFI.pinLength} digits`;

export function createCefiAuth(d: CefiAuthDeps) {
  const lockout = new PinLockout(d.storage);

  return betterAuth({
    appName: CEFI.rpName,
    baseURL: d.baseURL,
    basePath: "/auth",
    secret: d.secret,
    database: drizzleAdapter(d.db, { provider: "sqlite", schema }),
    secondaryStorage: d.storage,
    trustedOrigins: d.origins,
    telemetry: { enabled: false },
    // Failed sign-ins would otherwise log a warning each; lockout covers them.
    logger: { level: "error" },

    user: { modelName: "cefi_user" },
    session: {
      modelName: "cefi_session",
      // Durable in SQLite; Redis is the fast path.
      storeSessionInDatabase: true,
      expiresIn: CEFI.sessionExpiresInSeconds,
    },
    account: { modelName: "cefi_account" },
    verification: { modelName: "cefi_verification" },

    emailAndPassword: {
      enabled: true,
      autoSignIn: true,
      minPasswordLength: CEFI.pinLength,
      maxPasswordLength: CEFI.pinLength,
      password: {
        hash: (pin) => hashPin(pin, d.pinPepper),
        verify: ({ hash, password }) => verifyPin(password, hash, d.pinPepper),
      },
    },

    rateLimit: {
      enabled: true,
      storage: "secondary-storage",
      window: 60,
      max: 60,
      customRules: { "/sign-in/username": { window: 60, max: 10 } },
    },
    advanced: {
      // nginx sets X-Real-IP and clears X-Forwarded-For (deploy/nginx-cefi.conf).
      ipAddress: { ipAddressHeaders: ["x-real-ip"] },
      cookiePrefix: "cefi",
    },

    plugins: [
      username({
        minUsernameLength: CEFI.accountNumberLength,
        maxUsernameLength: CEFI.accountNumberLength,
        usernameNormalization: normalizeAccountNumber,
        usernameValidator: isAccountNumber,
        validationOrder: { username: "post-normalization" },
        displayUsername: false,
      }),
      passkey({
        rpID: d.rpID,
        rpName: CEFI.rpName,
        origin: d.origins,
        // Discoverable + biometric: sign in with one tap, no account number typed.
        authenticatorSelection: { residentKey: "required", userVerification: "required" },
        schema: { passkey: { modelName: "cefi_passkey" } },
      }),
    ],

    hooks: {
      before: createAuthMiddleware(async (ctx) => {
        if (ctx.path === "/sign-up/email" && !isValidPin(ctx.body?.password)) {
          throw new APIError("BAD_REQUEST", { message: PIN_ERROR });
        }
        if (ctx.path === "/change-password" && !isValidPin(ctx.body?.newPassword)) {
          throw new APIError("BAD_REQUEST", { message: PIN_ERROR });
        }
        if (ctx.path === "/sign-in/username") {
          const account = normalizeAccountNumber(String(ctx.body?.username ?? ""));
          const wait = await lockout.lockedFor(account);
          if (wait > 0) {
            throw new APIError("TOO_MANY_REQUESTS", {
              message: `Too many wrong PINs. Try again in ${Math.ceil(wait / 60)} min, or sign in with your passkey.`,
            }, { "Retry-After": String(wait) });
          }
          if (!isValidPin(ctx.body?.password)) {
            throw new APIError("BAD_REQUEST", { message: PIN_ERROR });
          }
        }
      }),
      after: createAuthMiddleware(async (ctx) => {
        if (ctx.path !== "/sign-in/username") return;
        const account = normalizeAccountNumber(String(ctx.body?.username ?? ""));
        const result = ctx.context.returned;
        if (isAPIError(result)) {
          if (result.statusCode === 401) await lockout.recordFailure(account);
        } else {
          await lockout.recordSuccess(account);
        }
      }),
    },
  });
}

export type CefiAuth = ReturnType<typeof createCefiAuth>;
